    "correct_answer": "A policy neither written nor expressed verbally that has developed over time following precedent",
    "explanation": "Leadership Rationale: In nursing leadership and management, \"A policy neither written nor expressed verbally that has developed over time following precedent\" is the verified administrative standard for \"Establishing Policies\". Implied policies are neither written nor expressed verbally, have developed over time, and follow a precedent.",
    "source_pdf_ref": "NCMB419_NLM_Midterms_Weeks_7-11.pdf, Page 14",
    "topic": "Establishing Policies",
    "approval_status": "approved"
